#include "communication_delivery_read.hpp"
#include "resident/storage/common_store.hpp"
namespace hanmo::resident {
bool same_communication_custodian(const CommunicationCustodian&a,const CommunicationCustodian&b){if(a.index()!=b.index())return false;if(const auto*x=std::get_if<CustodianActor>(&a))return x->actor_id==std::get<CustodianActor>(b).actor_id;return std::get<DeliverableProp>(a).prop_id==std::get<DeliverableProp>(b).prop_id;}
bool same_registered_communication_address(const RegisteredAddress&a,const RegisteredAddress&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if constexpr(std::is_same_v<T,ActorAddress>)return x.actor_id==y.actor_id;else if constexpr(std::is_same_v<T,CustodyAddress>)return x.receiver_actor_id==y.receiver_actor_id&&x.place_id==y.place_id&&same_communication_custodian(x.custodian,y.custodian);else return x.organization_id==y.organization_id&&x.office_id==y.office_id&&x.scope.kind==y.scope.kind&&x.scope.id==y.scope.id&&x.site_id==y.site_id&&x.delivery_policy==y.delivery_policy&&x.required_service_kind==y.required_service_kind;},a);}
Status validate_registered_communication_address(const RegisteredAddress&a){const bool valid=std::visit([](const auto&v){using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,ActorAddress>)return !v.actor_id.empty();else if constexpr(std::is_same_v<T,CustodyAddress>)return !v.receiver_actor_id.empty()&&!v.place_id.empty()&&std::visit([](const auto&c){using C=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<C,CustodianActor>)return !c.actor_id.empty();else return !c.prop_id.empty();},v.custodian);else return !v.organization_id.empty()&&!v.office_id.empty()&&!v.scope.id.empty()&&!v.site_id.empty()&&!v.required_service_kind.empty()&&(v.delivery_policy==RoleDeliveryPolicy::current_authorized_holder||v.delivery_policy==RoleDeliveryPolicy::institutional_custody);},a);return valid?common_success():common_failure("OfficialAddressInvalid");}
Status validate_official_content_ref(const OfficialContentRef&r){if(r.id.empty()||static_cast<Integer>(r.kind)<0||static_cast<Integer>(r.kind)>20)return common_failure("OfficialContentVersionUnavailable");
 // Proposal identity is the original proposal2 fact, while this version is
 // its immutable original treaty terms revision, never parsed from the ID.
 if(r.kind==OfficialContentKind::treaty_aid_resource_proposal){const auto*revision=std::get_if<Revision>(&r.terms_revision);if(!revision||revision->revision<1)return common_failure("TreatyAidProposalOfficialRevisionRequired",r.id);}
 return validate_terms_revision(r.terms_revision);}
const char* message_channel_name(MessageChannelKind channel)noexcept{switch(channel){case MessageChannelKind::face_to_face:return "face_to_face";case MessageChannelKind::custodian_pickup:return "custodian_pickup";case MessageChannelKind::carrier_delivery:return "carrier_delivery";case MessageChannelKind::scheduled_role_report:return "scheduled_role_report";}return nullptr;}
Outcome<MessageChannelKind> read_message_channel_kind(const StableId&name){for(Integer n=0;n<4;++n){const auto kind=static_cast<MessageChannelKind>(n);if(name==message_channel_name(kind))return {true,kind,{}};}return {false,{},common_failure("CommunicationChannelNotRegistered",name,ErrorKind::unsupported_capability).error};}
}
